contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that performs the property test
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // require that the test contract has enough balance to forward `amount` to c
        require(address(this).balance >= amount);

        // observe pre-call public values
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balCBefore = address(c).balance;

        // make the state-changing call; capture whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-call public values
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balCAfter = address(c).balance;

        // The general invariant we assert:
        // - bank address does not change
        // - if the call reverted then nothing in c changed (pot and balance unchanged)
        // - if the call did not revert then either:
        //     a) pot increased by exactly the ticket amount (no payout happened), or
        //     b) pot became 0 and the contract balance reflects that the pot was paid out (decrease)
        // We express this precisely below. Avoid underflow by comparing balances via sums.
        assert(
            // bank unchanged
            bankBefore == bankAfter
            && (
                // reverted: no observable change
                (reverted && potAfter == potBefore && balCAfter == balCBefore)
                ||
                // not reverted: exactly one of the two allowed outcomes
                (!reverted && (
                    // outcome 1: pot increased by amount and contract balance increased by amount
                    (potAfter == potBefore + amount && balCAfter == balCBefore + amount)
                    ||
                    // outcome 2: pot reset to 0 and contract balance decreased by (potBefore + amount - fee)
                    // But the contract sends FEE_AMOUNT to bank and (potBefore + amount - FEE_AMOUNT) to caller.
                    // We cannot reference FEE_AMOUNT or TICKET_AMOUNT constants directly here, so reason with observable values:
                    // If potAfter == 0 then the contract balance must be less than or equal to balCBefore + amount (because it may have transferred out funds).
                    // More strictly: when potAfter==0 the new contract balance equals balCBefore + amount - (potBefore + amount) = balCBefore - potBefore
                    // because the whole pot (old pot + amount) was paid out from the contract except fee sent to bank which reduces contract balance by potBefore + amount.
                    // Since we cannot read transfers to external accounts, we assert potAfter==0 implies balCAfter + potBefore == balCBefore
                    (potAfter == 0 && balCAfter + potBefore == balCBefore)
                ))
            )
        );
    }

    // receive to allow this contract to accept refunds/payments from C
    receive() external payable {}
}

